// Original procedural minor-key soundtrack. Starts only from the user's button click.
export function mountSoundtrack(getState=()=>null){if(document.querySelector('.soundtrack-dock'))return;const voices=new Set();let context,master,timer,next=0,step=0,on=false,volume=.18;try{const stored=Number(localStorage.getItem('moneyLabMusicVolume')||.18);volume=Number.isFinite(stored)?Math.max(0,Math.min(.4,stored)):.18;}catch{}
const dock=document.createElement('div');dock.className='soundtrack-dock';dock.innerHTML='<button type="button" aria-pressed="false"></button><small>♪ 96 BPM</small><input type="range" min="0" max="40" step="1">';document.body.append(dock);const button=dock.querySelector('button'),slider=dock.querySelector('input');slider.value=String(Math.round(volume*100));
function labels(){const vi=document.documentElement.lang!=='en';button.textContent=on?(vi?'Ⅱ Tắt nhạc nền':'Ⅱ Music off'):(vi?'♫ Bật nhạc nền':'♫ Music on');button.setAttribute('aria-pressed',String(on));slider.setAttribute('aria-label',vi?'Âm lượng nhạc nền':'Background music volume');dock.setAttribute('aria-label',vi?'Nhạc nền chinh phục bản đồ':'Map challenge soundtrack');}
function tone(freq,time,duration,type,level){const osc=context.createOscillator(),gain=context.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(0,time);gain.gain.linearRampToValueAtTime(level,time+.015);gain.gain.exponentialRampToValueAtTime(.0001,time+duration);osc.connect(gain);gain.connect(master);voices.add(osc);osc.onended=()=>voices.delete(osc);osc.start(time);osc.stop(time+duration+.03);}
function schedule(){if(!on||context.state!=='running')return;const s=getState(),hard=s?.difficulty==='hard',notes=hard?[146.83,174.61,220,261.63]:[130.81,155.56,196,233.08],pattern=[0,2,1,3,0,1,2,1,0,2,3,2,1,0,2,1];while(next<context.currentTime+.35){const n=pattern[step%16];tone(notes[n]*(step%8===7?2:1),next,.24,'triangle',.11);if(step%4===0){tone(notes[0]/2,next,.55,'sine',.3);tone(52,next,.10,'sine',.22);}if(hard&&step%4===2)tone(65,next,.10,'sine',.13);next+=60/96/2;step++;}}
async function start(){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){button.textContent='Audio unavailable';return;}context??=new Audio();if(!master){master=context.createGain();master.gain.value=volume;const compressor=context.createDynamicsCompressor();master.connect(compressor);compressor.connect(context.destination);}await context.resume();on=true;next=context.currentTime+.05;timer=setInterval(schedule,100);schedule();labels();}
function clearVoices(){for(const osc of voices){try{osc.stop();}catch{}}voices.clear();}
async function stop(){on=false;clearInterval(timer);clearVoices();if(context)await context.suspend();labels();}button.onclick=async()=>{try{if(on)await stop();else await start();}catch{on=false;clearInterval(timer);labels();}};slider.oninput=()=>{volume=Number(slider.value)/100;if(master)master.gain.setTargetAtTime(volume,context.currentTime,.05);try{localStorage.setItem('moneyLabMusicVolume',String(volume));}catch{}};
document.addEventListener('visibilitychange',async()=>{if(!on||!context)return;try{if(document.hidden){clearVoices();await context.suspend();}else{await context.resume();next=context.currentTime+.05;}}catch{await stop();}});new MutationObserver(labels).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});labels();}
